const readline = require('readline');

const rl = readline.createInterface({
    input: process.stdin,
    output: process.stdout
});

let n = 0;
let s = '';
let lineCount = 0;

rl.on('line', (line) => {
    if (lineCount === 0) {
        n = parseInt(line.trim(), 10);
    } else if (lineCount === 1) {
        s = line.trim();
        // Process after reading both lines
        let count = 0;
        let removals = 0;
        for (let i = 0; i < n; i++) {
            if (s[i] === 'x') {
                count++;
                if (count >= 3) {
                    removals++;
                }
            } else {
                count = 0;
            }
        }
        console.log(removals);
        rl.close();
    }
    lineCount++;
});
